"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SWITCH: on and off, with weight
 *
 *   press    the thumb stretches toward the side it will go
 *   flip     it's thrown across with a slight overshoot while the
 *            track fills; the fill and thumb move as one
 *   async    if onCheckedChange returns a promise, the switch
 *            flips at once and the thumb spins until it settles;
 *            a rejection throws it back and shakes the track
 * ───────────────────────────────────────────────────────── */

export interface SwitchProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onChange" | "value"
> {
  checked?: boolean;
  defaultChecked?: boolean;
  /** Return a promise to show the pending thumb; throw to put it back. */
  onCheckedChange?: (checked: boolean) => void | Promise<unknown>;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** 16px or 20px tall. */
  size?: "sm" | "md";
  /** Put the label before the switch (settings rows). */
  labelPosition?: "start" | "end";
  ref?: React.Ref<HTMLButtonElement>;
}

const SIZES = { sm: { w: 28, h: 16, pad: 2 }, md: { w: 36, h: 20, pad: 2 } };

export function Switch({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  size = "md",
  labelPosition = "end",
  disabled,
  className = "",
  id,
  ref,
  ...props
}: SwitchProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const switchId = id ?? auto;
  const track = React.useRef<HTMLSpanElement>(null);
  const [own, setOwn] = React.useState(defaultChecked);
  const [optimistic, setOptimistic] = React.useState<boolean | null>(null);
  const [pressed, setPressed] = React.useState(false);
  const on = optimistic ?? (checked !== undefined ? checked : own);
  const pending = optimistic !== null;
  const s = SIZES[size];
  const thumb = s.h - s.pad * 2;
  const travel = s.w - thumb - s.pad * 2;
  const stretch = pressed && !reduced ? 4 : 0;

  const toggle = () => {
    if (disabled || pending) return;
    const next = !on;
    const result = onCheckedChange?.(next);
    if (result && typeof (result as Promise<unknown>).then === "function") {
      setOptimistic(next);
      (result as Promise<unknown>).then(
        () => {
          if (checked === undefined) setOwn(next);
          setOptimistic(null);
        },
        () => {
          setOptimistic(null);
          if (!reduced)
            track.current?.animate(
              [
                { transform: "none" },
                { transform: "translateX(-3px)" },
                { transform: "translateX(3px)" },
                { transform: "none" },
              ],
              { duration: 320, easing: "ease-out" },
            );
        },
      );
    } else if (checked === undefined) setOwn(next);
  };

  const control = (
    <button
      ref={ref}
      id={switchId}
      type="button"
      role="switch"
      aria-checked={on}
      aria-busy={pending || undefined}
      disabled={disabled}
      onClick={toggle}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
      onBlur={() => setPressed(false)}
      className={`relative inline-flex shrink-0 rounded-full cursor-pointer disabled:cursor-default disabled:opacity-50 ${INTERACTION_FOCUS}`}
      style={{ width: s.w, height: s.h }}
      {...props}
    >
      <span
        ref={track}
        className="absolute inset-0 overflow-hidden rounded-full bg-[color-mix(in_oklab,var(--foreground)_12%,var(--muted))] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
      >
        <span
          className="absolute inset-0 rounded-full bg-primary"
          style={{
            opacity: on ? 1 : 0,
            transition: reduced ? "none" : `opacity 260ms ${EASE_OUT}`,
          }}
        />
      </span>
      <span
        className="absolute rounded-full bg-background shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
        style={{
          top: s.pad,
          left: s.pad,
          height: thumb,
          width: thumb + stretch,
          // Stretching toward where it's going: grow from the far edge when on.
          transform: `translateX(${on ? travel - stretch : 0}px)`,
          transition: reduced
            ? "none"
            : `transform 420ms ${EASE_THROW}, width 260ms ${EASE_OUT}`,
        }}
      >
        <span
          className="absolute inset-0 flex items-center justify-center text-primary"
          style={interactionIcon(pending, reduced)}
        >
          <span
            className={`size-[60%] rounded-full border-[1.5px] border-current border-t-transparent ${pending ? "animate-spin" : ""}`}
          />
        </span>
      </span>
    </button>
  );

  if (!label && !description)
    return <span className={className}>{control}</span>;

  return (
    <div
      className={`flex items-start gap-3 ${labelPosition === "start" ? "flex-row-reverse justify-between" : ""} ${className}`}
    >
      <span className="mt-0.5">{control}</span>
      <label
        htmlFor={switchId}
        className={`flex min-w-0 flex-col gap-0.5 ${disabled ? "opacity-50" : "cursor-pointer"}`}
      >
        {label && (
          <span className="text-[13.5px] font-medium leading-5 text-foreground">
            {label}
          </span>
        )}
        {description && (
          <span className="text-[12.5px] leading-snug text-muted-foreground">
            {description}
          </span>
        )}
      </label>
    </div>
  );
}

export default Switch;

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}
